    "gray-matter": "^4.0.3",
    "marked": "^12.0.2"
  },
  "devDependencies": {
    "@types/jest": "^29.5.12",
    "@types/node": "^20.14.9",
    "jest": "^29.7.0",
    "ts-jest": "^29.1.5",
    "typescript": "^5.5.3"
  }
}

export interface FrontMatter {
  title?: string;
  date?: string;
  tags?: string[];
  [key: string]: unknown;
}

export interface Page {
  /** Path to the source markdown file, relative to the content directory. */
  sourcePath: string;
  /** URL-friendly slug derived from the source path, without extension. */
  slug: string;
  /** Output file name, e.g. "about.html". */
  outputFile: string;
  title: string;
  date: string | undefined;
  tags: string[];
  html: string;
}

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
}

export interface BuildResult {
  pages: Page[];
  outputDir: string;
}

import matter from 'gray-matter';
import { marked } from 'marked';
import * as path from 'path';
import { FrontMatter, Page } from './types';

marked.setOptions({ gfm: true });

/**
 * Turns a source-relative markdown path into a title-cased fallback title,
 * used when a page has no frontmatter title.
 */
function titleFromSlug(slug: string): string {
  const base = slug.split('/').pop() || slug;
  return base
    .replace(/[-_]+/g, ' ')
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

function normalizeTags(rawTags: unknown): string[] {
  if (Array.isArray(rawTags)) {
    return rawTags.map((t) => String(t));
  }
  if (typeof rawTags === 'string' && rawTags.trim().length > 0) {
    return rawTags.split(',').map((t) => t.trim());
  }
  return [];
}

function normalizeDate(rawDate: unknown): string | undefined {
  if (rawDate === undefined || rawDate === null) return undefined;
  if (rawDate instanceof Date) return rawDate.toISOString().slice(0, 10);
  return String(rawDate);
}

/**
 * Parses a single markdown file's raw text (with optional frontmatter) into
 * a Page. `relativePath` is the file's path relative to the content
 * directory, using forward slashes, e.g. "posts/hello-world.md".
 */
export function parseMarkdown(raw: string, relativePath: string): Page {
  const { data, content } = matter(raw);
  const frontMatter = data as FrontMatter;

  const parsedPath = path.posix.parse(relativePath.split(path.sep).join('/'));
  const slug = parsedPath.dir ? `${parsedPath.dir}/${parsedPath.name}` : parsedPath.name;

  const html = marked.parse(content, { async: false }) as string;

  return {
    sourcePath: relativePath,
    slug,
    outputFile: `${slug}.html`,
    title: frontMatter.title ? String(frontMatter.title) : titleFromSlug(slug),
    date: normalizeDate(frontMatter.date),
    tags: normalizeTags(frontMatter.tags),
    html,
  };
}

import { Page } from './types';

export function escapeHtml(input: string): string {
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export function renderPage(page: Page): string {
  const tagsHtml = page.tags.length
    ? `<ul class="tags">${page.tags.map((t) => `<li>${escapeHtml(t)}</li>`).join('')}</ul>`
    : '';
  const dateHtml = page.date ? `<time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>` : '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${escapeHtml(page.title)}</title>
<link rel="stylesheet" href="style.css">
</head>
<body>
<header>
<a href="index.html">&larr; Home</a>
</header>
<article>
<h1>${escapeHtml(page.title)}</h1>
${dateHtml}
${tagsHtml}
${page.html}
</article>
</body>
</html>
`;
}

export function renderIndex(pages: Page[]): string {
  const sorted = [...pages].sort((a, b) => (b.date || '').localeCompare(a.date || ''));
  const items = sorted
    .map((page) => {
      const dateHtml = page.date ? ` <time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>` : '';
      return `<li><a href="${escapeHtml(page.outputFile)}">${escapeHtml(page.title)}</a>${dateHtml}</li>`;
    })
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Home</title>
<link rel="stylesheet" href="style.css">
</head>
<body>
<header>
<h1>Home</h1>
</header>
<ul class="page-list">
${items}
</ul>
</body>
</html>
`;
}

import * as fs from 'fs';
import * as path from 'path';
import { parseMarkdown } from './parser';
import { renderIndex, renderPage } from './templates';
import { BuildOptions, BuildResult, Page } from './types';

const MARKDOWN_EXTENSIONS = new Set(['.md', '.markdown']);

/**
 * Recursively finds markdown files under `dir`, returning paths relative to
 * `dir` (using forward slashes).
 */
export function findMarkdownFiles(dir: string): string[] {
  const results: string[] = [];

  function walk(current: string) {
    const entries = fs.readdirSync(current, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(current, entry.name);
      if (entry.isDirectory()) {
        walk(fullPath);
      } else if (MARKDOWN_EXTENSIONS.has(path.extname(entry.name).toLowerCase())) {
        results.push(path.relative(dir, fullPath).split(path.sep).join('/'));
      }
    }
  }

  if (fs.existsSync(dir)) {
    walk(dir);
  }

  return results;
}

export function loadPages(contentDir: string): Page[] {
  const files = findMarkdownFiles(contentDir);
  return files.map((relativePath) => {
    const raw = fs.readFileSync(path.join(contentDir, relativePath), 'utf-8');
    return parseMarkdown(raw, relativePath);
  });
}

function writeFile(filePath: string, contents: string) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, contents, 'utf-8');
}

const DEFAULT_STYLESHEET = `body { font-family: sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.6; }
header { margin-bottom: 2rem; }
.page-list { list-style: none; padding: 0; }
.page-list li { margin-bottom: 0.5rem; }
.tags { list-style: none; padding: 0; display: flex; gap: 0.5rem; }
.tags li { background: #eee; border-radius: 0.25rem; padding: 0.1rem 0.5rem; font-size: 0.85rem; }
`;

export function buildSite(options: BuildOptions): BuildResult {
  const { contentDir, outputDir } = options;

  if (!fs.existsSync(contentDir)) {
    throw new Error(`Content directory not found: ${contentDir}`);
  }

  const pages = loadPages(contentDir);

  fs.mkdirSync(outputDir, { recursive: true });

  for (const page of pages) {
    writeFile(path.join(outputDir, page.outputFile), renderPage(page));
  }

  writeFile(path.join(outputDir, 'index.html'), renderIndex(pages));
  writeFile(path.join(outputDir, 'style.css'), DEFAULT_STYLESHEET);

  return { pages, outputDir };
}

#!/usr/bin/env node
import { Command } from 'commander';
import * as path from 'path';
import { buildSite } from './generator';

export function run(argv: string[]): void {
  const program = new Command();

  program.name('ssg').description('A static site generator').version('1.0.0');

  program
    .command('build')
    .description('Generate the site from Markdown content')
    .option('--content <dir>', 'content directory', './content')
    .option('--output <dir>', 'output directory', './dist')
    .action((opts: { content: string; output: string }) => {
      const contentDir = path.resolve(process.cwd(), opts.content);
      const outputDir = path.resolve(process.cwd(), opts.output);
      const result = buildSite({ contentDir, outputDir });
      // eslint-disable-next-line no-console
      console.log(`Built ${result.pages.length} page(s) into ${result.outputDir}`);
    });

  program.parse(argv);
}

if (require.main === module) {
  run(process.argv);
}

export { buildSite, loadPages, findMarkdownFiles } from './generator';
export { parseMarkdown } from './parser';
export { renderPage, renderIndex } from './templates';
export * from './types';

import { parseMarkdown } from '../src/parser';

describe('parseMarkdown', () => {
  it('extracts frontmatter fields', () => {
    const raw = `---
title: Hello World
date: 2024-01-15
tags: [intro, news]
---

# Hi there

Some *content*.
`;
    const page = parseMarkdown(raw, 'hello-world.md');

    expect(page.title).toBe('Hello World');
    expect(page.date).toBe('2024-01-15');
    expect(page.tags).toEqual(['intro', 'news']);
    expect(page.slug).toBe('hello-world');
    expect(page.outputFile).toBe('hello-world.html');
  });

  it('renders markdown body to HTML', () => {
    const raw = `---
title: Test
---
# Heading

A paragraph with **bold** text.
`;
    const page = parseMarkdown(raw, 'test.md');

    expect(page.html).toContain('<h1>Heading</h1>');
    expect(page.html).toContain('<strong>bold</strong>');
  });

  it('falls back to a title derived from the filename when missing', () => {
    const raw = `No frontmatter here.\n`;
    const page = parseMarkdown(raw, 'my-cool-post.md');

    expect(page.title).toBe('My Cool Post');
  });

  it('handles comma-separated string tags', () => {
    const raw = `---
title: Tagged
tags: "one, two, three"
---
Body
`;
    const page = parseMarkdown(raw, 'tagged.md');

    expect(page.tags).toEqual(['one', 'two', 'three']);
  });

  it('defaults tags to an empty array when absent', () => {
    const raw = `---
title: No Tags
---
Body
`;
    const page = parseMarkdown(raw, 'no-tags.md');

    expect(page.tags).toEqual([]);
  });

  it('preserves nested directory structure in the slug', () => {
    const raw = `---
title: Nested
---
Body
`;
    const page = parseMarkdown(raw, 'posts/2024/nested.md');

    expect(page.slug).toBe('posts/2024/nested');
    expect(page.outputFile).toBe('posts/2024/nested.html');
  });

  it('leaves date undefined when absent from frontmatter', () => {
    const raw = `---
title: No Date
---
Body
`;
    const page = parseMarkdown(raw, 'no-date.md');

    expect(page.date).toBeUndefined();
  });
});

import { renderIndex, renderPage } from '../src/templates';
import { Page } from '../src/types';

function makePage(overrides: Partial<Page> = {}): Page {
  return {
    sourcePath: 'hello.md',
    slug: 'hello',
    outputFile: 'hello.html',
    title: 'Hello',
    date: '2024-01-01',
    tags: ['a', 'b'],
    html: '<p>Body</p>',
    ...overrides,
  };
}

describe('renderPage', () => {
  it('includes the title, date, tags and body html', () => {
    const html = renderPage(makePage());

    expect(html).toContain('<title>Hello</title>');
    expect(html).toContain('<h1>Hello</h1>');
    expect(html).toContain('2024-01-01');
    expect(html).toContain('<li>a</li>');
    expect(html).toContain('<li>b</li>');
    expect(html).toContain('<p>Body</p>');
  });

  it('escapes HTML-sensitive characters in the title', () => {
    const html = renderPage(makePage({ title: '<script>alert(1)</script>' }));

    expect(html).not.toContain('<script>alert(1)</script>');
    expect(html).toContain('&lt;script&gt;');
  });

  it('omits the tags list when there are no tags', () => {
    const html = renderPage(makePage({ tags: [] }));

    expect(html).not.toContain('class="tags"');
  });
});

describe('renderIndex', () => {
  it('lists all pages sorted by date descending', () => {
    const older = makePage({ slug: 'older', outputFile: 'older.html', title: 'Older', date: '2023-01-01' });
    const newer = makePage({ slug: 'newer', outputFile: 'newer.html', title: 'Newer', date: '2024-06-01' });

    const html = renderIndex([older, newer]);

    const newerIndex = html.indexOf('Newer');
    const olderIndex = html.indexOf('Older');
    expect(newerIndex).toBeGreaterThan(-1);
    expect(olderIndex).toBeGreaterThan(-1);
    expect(newerIndex).toBeLessThan(olderIndex);
  });

  it('links to each page output file', () => {
    const page = makePage();
    const html = renderIndex([page]);

    expect(html).toContain('href="hello.html"');
  });
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { buildSite, findMarkdownFiles, loadPages } from '../src/generator';

function makeTmpDir(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-test-'));
}

describe('findMarkdownFiles', () => {
  let contentDir: string;

  beforeEach(() => {
    contentDir = makeTmpDir();
  });

  afterEach(() => {
    fs.rmSync(contentDir, { recursive: true, force: true });
  });

  it('returns an empty array for a missing directory', () => {
    expect(findMarkdownFiles(path.join(contentDir, 'does-not-exist'))).toEqual([]);
  });

  it('finds .md files recursively and ignores other extensions', () => {
    fs.writeFileSync(path.join(contentDir, 'a.md'), '# A');
    fs.writeFileSync(path.join(contentDir, 'notes.txt'), 'ignore me');
    fs.mkdirSync(path.join(contentDir, 'nested'));
    fs.writeFileSync(path.join(contentDir, 'nested', 'b.markdown'), '# B');

    const files = findMarkdownFiles(contentDir).sort();

    expect(files).toEqual(['a.md', 'nested/b.markdown']);
  });
});

describe('loadPages', () => {
  let contentDir: string;

  beforeEach(() => {
    contentDir = makeTmpDir();
  });

  afterEach(() => {
    fs.rmSync(contentDir, { recursive: true, force: true });
  });

  it('parses every markdown file into a Page', () => {
    fs.writeFileSync(
      path.join(contentDir, 'first.md'),
      '---\ntitle: First\n---\nFirst body'
    );
    fs.writeFileSync(
      path.join(contentDir, 'second.md'),
      '---\ntitle: Second\n---\nSecond body'
    );

    const pages = loadPages(contentDir).sort((a, b) => a.slug.localeCompare(b.slug));

    expect(pages).toHaveLength(2);
    expect(pages[0].title).toBe('First');
    expect(pages[1].title).toBe('Second');
  });
});

describe('buildSite', () => {
  let contentDir: string;
  let outputDir: string;

  beforeEach(() => {
    contentDir = makeTmpDir();
    outputDir = makeTmpDir();
  });

  afterEach(() => {
    fs.rmSync(contentDir, { recursive: true, force: true });
    fs.rmSync(outputDir, { recursive: true, force: true });
  });

  it('throws when the content directory does not exist', () => {
    expect(() =>
      buildSite({ contentDir: path.join(contentDir, 'missing'), outputDir })
    ).toThrow(/Content directory not found/);
  });

  it('writes a per-page HTML file and an index.html', () => {
    fs.writeFileSync(
      path.join(contentDir, 'about.md'),
      '---\ntitle: About\ndate: 2024-02-02\ntags: [meta]\n---\n# About us'
    );

    const result = buildSite({ contentDir, outputDir });

    expect(result.pages).toHaveLength(1);
    expect(fs.existsSync(path.join(outputDir, 'about.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);

    const pageHtml = fs.readFileSync(path.join(outputDir, 'about.html'), 'utf-8');
    expect(pageHtml).toContain('<h1>About</h1>');

    const indexHtml = fs.readFileSync(path.join(outputDir, 'index.html'), 'utf-8');
    expect(indexHtml).toContain('href="about.html"');
    expect(indexHtml).toContain('About');
  });

  it('creates an empty index when there is no content', () => {
    const result = buildSite({ contentDir, outputDir });

    expect(result.pages).toEqual([]);
    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);
  });

  it('preserves nested directory structure in the output', () => {
    fs.mkdirSync(path.join(contentDir, 'posts'));
    fs.writeFileSync(
      path.join(contentDir, 'posts', 'first-post.md'),
      '---\ntitle: First Post\n---\nBody'
    );

    buildSite({ contentDir, outputDir });

    expect(fs.existsSync(path.join(outputDir, 'posts', 'first-post.html'))).toBe(true);
  });
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { run } from '../src/cli';

function makeTmpDir(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-cli-test-'));
}

describe('ssg build CLI', () => {
  let contentDir: string;
  let outputDir: string;
  let logSpy: jest.SpyInstance;

  beforeEach(() => {
    contentDir = makeTmpDir();
    outputDir = makeTmpDir();
    fs.writeFileSync(
      path.join(contentDir, 'page.md'),
      '---\ntitle: CLI Page\n---\nHello from the CLI'
    );
    logSpy = jest.spyOn(console, 'log').mockImplementation(() => undefined);
  });

  afterEach(() => {
    fs.rmSync(contentDir, { recursive: true, force: true });
    fs.rmSync(outputDir, { recursive: true, force: true });
    logSpy.mockRestore();
  });

  it('builds the site using --content and --output options', () => {
    run(['node', 'ssg', 'build', '--content', contentDir, '--output', outputDir]);

    expect(fs.existsSync(path.join(outputDir, 'page.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);
    expect(logSpy).toHaveBeenCalledWith(expect.stringContaining('Built 1 page(s)'));
  });
});
